266	function diffExecutionParticipants(
267	  previousPolicy: NormalizedExecutionPolicy | null,
268	  nextPolicy: NormalizedExecutionPolicy | null,
269	  stageType: NormalizedExecutionPolicy["stages"][number]["type"],
270	) {
271	  const previousParticipants = summarizeExecutionParticipants(previousPolicy, stageType);
272	  const nextParticipants = summarizeExecutionParticipants(nextPolicy, stageType);
273	  const previousByKey = new Map(previousParticipants.map((participant) => [
274	    activityExecutionParticipantKey(participant),
275	    participant,
276	  ]));
277	  const nextByKey = new Map(nextParticipants.map((participant) => [
278	    activityExecutionParticipantKey(participant),
279	    participant,
280	  ]));
281	
282	  return {
283	    participants: nextParticipants,
284	    addedParticipants: nextParticipants.filter((participant) => !previousByKey.has(activityExecutionParticipantKey(participant))),
285	    removedParticipants: previousParticipants.filter((participant) => !nextByKey.has(activityExecutionParticipantKey(participant))),
