312	      state: nextState,
313	      wakeRole: nextState.currentStageType === "approval" ? "approver" : "reviewer",
314	      allowedActions: ["approve", "request_changes"],
315	    });
316	
317	    return {
318	      agentId,
319	      wakeup: {
320	        source: "assignment" as const,
321	        triggerDetail: "system" as const,
322	        reason,
323	        payload: {
