35	export function parseCostLimit(query: Record<string, unknown>) {
36	  const raw = Array.isArray(query.limit) ? query.limit[0] : query.limit;
37	  if (raw == null || raw === "") return 100;
38	  const limit = typeof raw === "number" ? raw : Number.parseInt(String(raw), 10);
39	  if (!Number.isFinite(limit) || limit <= 0 || limit > 500) {
40	    throw badRequest("invalid 'limit' value");
41	  }
42	  return limit;
43	}
