19	async function waitForRunCancellationTasks(tasks: Promise<void>[]) {
20	  let timeout: ReturnType<typeof setTimeout> | null = null;
21	  try {
22	    await Promise.race([
23	      Promise.all(tasks),
24	      new Promise((resolve) => {
25	        timeout = setTimeout(resolve, TREE_RUN_CANCELLATION_RESPONSE_WAIT_MS);
26	      }),
27	    ]);
28	  } finally {
29	    if (timeout) clearTimeout(timeout);
30	  }
